import { screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ApiError, type ApiClient } from '@/lib/api/client';
import { groupsApi, konferenca, skupno, signedIn } from '@/test/groupsApi';
import { renderApp } from '@/test/renderApp';

type Reply = (method: string, path: string, body?: unknown) => unknown;

const ana = {
  id: 'c/1',
  state: 'ACTIVE',
  revision: 7,
  versionNumber: 2,
  createdAt: '2026-11-10T10:00:00Z',
  firstName: 'Ana',
  lastName: 'Novak',
  phone: '+386 41 555 123',
};
const stamp = '2026-07-01T22:30:00Z';

function fake(overrides: Reply = () => undefined, versions: unknown = [{ number: 1, userName: 'Marko', createdAt: stamp }]) {
  const { api: groups } = groupsApi([konferenca, skupno]);
  const calls: { method: string; path: string; body?: unknown }[] = [];
  const api: ApiClient = {
    ...groups,
    request: (async (method: string, path: string, body?: unknown) => {
      if (path.startsWith('/groups/g-1/contacts/')) {
        calls.push({ method, path, body });
        const own = overrides(method, path, body);
        if (own !== undefined) return own;
        if (path.endsWith('/versions')) return versions;
        if (/\/versions\/1$/.test(path))
          return { number: 1, userName: 'Marko', createdAt: stamp, snapshot: { firstName: 'Ana', lastName: 'Novak', phone: '+386 40 000 111' } };
        if (path.endsWith('/restore')) return { ...ana, revision: 8 };
        return ana;
      }
      return groups.request(method, path, body);
    }) as ApiClient['request'],
  };
  return { api, calls };
}

const URL_ = '/groups/g-1/contacts/c%2F1/versions';
const open = (f: ReturnType<typeof fake>, path = URL_) => renderApp(path, { auth: signedIn(), api: f.api });
const row = async () => (await screen.findByText('Version 1')).closest('tr') as HTMLElement;
const fail = (code: string) => () => {
  throw new ApiError(409, { status: 409, code, message: 'x' } as never);
};

describe('VersionsPage: requests and navigation', () => {
  it('reads the list and the contact once each, with the ids encoded', async () => {
    const f = fake();
    open(f);
    await row();
    await waitFor(() => expect(f.calls.filter((c) => c.path === '/groups/g-1/contacts/c%2F1')).toHaveLength(1));
    expect(f.calls.filter((c) => c.path.endsWith('/versions'))).toEqual([
      { method: 'GET', path: '/groups/g-1/contacts/c%2F1/versions', body: undefined },
    ]);
    expect(f.calls.some((c) => /versions\/\d+$/.test(c.path))).toBe(false);
  });

  it('does not read the contact again when the window gets focus', async () => {
    const f = fake();
    open(f);
    await row();
    await waitFor(() => expect(f.calls.some((c) => c.path === '/groups/g-1/contacts/c%2F1')).toBe(true));
    window.dispatchEvent(new Event('focus'));
    document.dispatchEvent(new Event('visibilitychange'));
    await new Promise((r) => setTimeout(r, 50));
    expect(f.calls.filter((c) => c.path === '/groups/g-1/contacts/c%2F1')).toHaveLength(1);
  });

  it('shows a Viewer nothing and asks for nothing', async () => {
    const f = fake();
    renderApp('/groups/g-3/contacts/c-1/versions', { auth: signedIn(), api: f.api });
    await screen.findByRole('heading', { name: 'Ana Novak' }).catch(() => undefined);
    await new Promise((r) => setTimeout(r, 50));
    expect(screen.queryByText('Version 1')).toBeNull();
    expect(screen.queryByRole('table')).toBeNull();
    expect(f.calls).toHaveLength(0);
  });

  it('links to the contacts, the details and the history, and marks the Versions tab', async () => {
    open(fake());
    await row();
    const crumb = screen.getByText(/\/ Contact$/);
    expect(within(crumb).getByRole('link', { name: 'Contacts' })).toHaveAttribute('href', '/groups/g-1');
    const nav = screen.getByRole('navigation', { name: 'Contact' });
    expect(within(nav).getByRole('link', { name: 'Details' })).toHaveAttribute('href', '/groups/g-1/contacts/c/1');
    expect(within(nav).getByRole('link', { name: 'History' })).toHaveAttribute('href', '/groups/g-1/contacts/c/1/history');
    expect(within(nav).getByText('Versions')).toHaveAttribute('aria-current', 'page');
    expect(screen.getByText(/\/ Contact$/)).toBeInTheDocument();
  });

  it('lists the column headings, the date and the three actions of a version', async () => {
    open(fake());
    const r = await row();
    const heads = screen.getAllByRole('columnheader').map((h) => h.textContent);
    expect(heads).toEqual(['Version', 'Who', 'When', 'Actions']);
    expect(within(r).getByText('Marko')).toBeInTheDocument();
    expect(r.querySelector('time')).toHaveAttribute('datetime', stamp);
    expect(r.querySelector('time')?.textContent).toMatch(/2026/);
    expect(within(r).getAllByRole('button').map((b) => b.textContent)).toEqual(['View', 'Compare', 'Restore']);
  });

  it('explains an empty list', async () => {
    open(fake(() => undefined, []));
    expect(await screen.findByRole('heading', { name: 'No versions yet' })).toBeInTheDocument();
    expect(screen.getByText('A version is recorded each time the contact is saved.')).toBeInTheDocument();
    expect(screen.queryByRole('table')).toBeNull();
  });

  it('shows an error with a retry that reads the list again', async () => {
    let failing = true;
    const f = fake((_m, path) => {
      if (path.endsWith('/versions') && failing) throw new ApiError(500, { status: 500, code: 'INTERNAL_ERROR', message: 'x' } as never);
      return undefined;
    });
    open(f);
    expect(await screen.findByText('Something went wrong. Please try again.')).toBeInTheDocument();
    failing = false;
    await userEvent.click(screen.getByRole('button', { name: 'Try again' }));
    expect(await screen.findByText('Version 1')).toBeInTheDocument();
  });
});

describe('VersionsPage: one version and the comparison', () => {
  it('opens version 1 with its heading, its values and the way back, and asks for that number', async () => {
    const f = fake();
    open(f);
    await userEvent.click(within(await row()).getByRole('button', { name: 'View' }));
    expect(await screen.findByRole('heading', { name: 'Version 1' })).toBeInTheDocument();
    expect(f.calls.some((c) => c.path === '/groups/g-1/contacts/c%2F1/versions/1' && c.method === 'GET')).toBe(true);
    expect(screen.getByText('+386 40 000 111')).toBeInTheDocument();
    expect(screen.getByRole('heading', { name: 'Details' })).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: 'Back to versions' }));
    expect(await screen.findByRole('table')).toBeInTheDocument();
    expect(screen.queryByRole('heading', { name: 'Version 1' })).toBeNull();
  });

  it('shows the tags and attributes a version holds', async () => {
    const f = fake((_m, path) =>
      /\/versions\/1$/.test(path)
        ? {
            number: 1,
            userName: 'Marko',
            createdAt: stamp,
            snapshot: { firstName: 'Ana', lastName: 'Novak', tags: ['vip'], attributes: [{ key: 'Level', value: 'gold' }] },
          }
        : undefined,
    );
    open(f);
    await userEvent.click(within(await row()).getByRole('button', { name: 'View' }));
    expect(await screen.findByText('vip')).toBeInTheDocument();
    expect(screen.getByText('Level')).toBeInTheDocument();
    expect(screen.getByText('gold')).toBeInTheDocument();
  });

  it('names the comparison, shows the current contact and goes back', async () => {
    open(fake());
    await userEvent.click(within(await row()).getByRole('button', { name: 'Compare' }));
    expect(await screen.findByRole('heading', { name: 'Compare versions' })).toBeInTheDocument();
    expect(screen.getByText('Highlighted rows differ.')).toBeInTheDocument();
    expect(screen.queryByRole('heading', { name: 'Details' })).toBeNull();
    await userEvent.click(screen.getByRole('button', { name: 'Back to versions' }));
    expect(await screen.findByRole('table')).toBeInTheDocument();
  });

  it('compares a contact and a version that hold no tags or attributes', async () => {
    open(fake());
    await userEvent.click(within(await row()).getByRole('button', { name: 'Compare' }));
    const first = (await screen.findByRole('rowheader', { name: /First name/ })).closest('tr') as HTMLElement;
    expect(within(first).queryByText('Changed')).toBeNull();
    expect(screen.queryByText('Stryker was here')).toBeNull();
  });

  it('shows a loading panel until the version arrives and an error with a retry when it fails', async () => {
    let failing = true;
    const f = fake((_m, path) => {
      if (/\/versions\/1$/.test(path) && failing) throw new ApiError(500, { status: 500, code: 'INTERNAL_ERROR', message: 'x' } as never);
      return undefined;
    });
    open(f);
    await userEvent.click(within(await row()).getByRole('button', { name: 'View' }));
    expect(await screen.findByText('Something went wrong. Please try again.')).toBeInTheDocument();
    failing = false;
    await userEvent.click(screen.getByRole('button', { name: 'Try again' }));
    expect(await screen.findByText('+386 40 000 111')).toBeInTheDocument();
  });

  it('opens the restore dialog from the version itself and restores that number', async () => {
    const f = fake();
    open(f);
    await userEvent.click(within(await row()).getByRole('button', { name: 'View' }));
    await screen.findByRole('heading', { name: 'Version 1' });
    await userEvent.click(screen.getByRole('button', { name: 'Restore this version' }));
    const dialog = await screen.findByRole('dialog');
    expect(within(dialog).getByRole('heading', { name: 'Restore this version' })).toBeInTheDocument();
    expect(within(dialog).getByText(/A new version is recorded; nothing is lost\./)).toBeInTheDocument();
    await userEvent.click(within(dialog).getByRole('button', { name: 'Restore this version' }));
    expect(await screen.findByText('The version was restored.')).toBeInTheDocument();
    expect(f.calls.filter((c) => c.method === 'POST')).toEqual([
      { method: 'POST', path: '/groups/g-1/contacts/c%2F1/versions/1/restore', body: { revision: 7 } },
    ]);
    expect(await screen.findByRole('table')).toBeInTheDocument();
  });
});

describe('VersionsPage: after a restore', () => {
  async function restoreFrom(f: ReturnType<typeof fake>) {
    open(f);
    await userEvent.click(within(await row()).getByRole('button', { name: 'Restore' }));
    await userEvent.click(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Restore this version' }));
  }

  it('says it as a status, reads the list and the contact list again and uses the new revision next time', async () => {
    const f = fake();
    await restoreFrom(f);
    const status = await screen.findByRole('status');
    expect(status).toHaveTextContent('The version was restored.');
    expect(screen.queryByRole('alert')).toBeNull();
    await waitFor(() => expect(f.calls.filter((c) => c.path.endsWith('/versions') && c.method === 'GET').length).toBeGreaterThan(1));
    await userEvent.click(within(await row()).getByRole('button', { name: 'Restore' }));
    await userEvent.click(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Restore this version' }));
    await waitFor(() => expect(f.calls.filter((c) => c.method === 'POST')).toHaveLength(2));
    expect(f.calls.filter((c) => c.method === 'POST')[1]?.body).toEqual({ revision: 8 });
  });

  it('shows a failure as an alert, names an unknown failure by the generic text, and keeps the view', async () => {
    const f = fake((m) => (m === 'POST' ? fail('CONFLICT')() : undefined));
    await restoreFrom(f);
    const alert = await screen.findByRole('alert');
    expect(alert).toHaveTextContent('This contact was changed by someone else.');
    expect(screen.queryByRole('status')).toBeNull();
    expect(screen.getByRole('table')).toBeInTheDocument();
  });

  it('treats a failure that is no ApiError as an internal error', async () => {
    const f = fake((m) => {
      if (m === 'POST') throw new Error('boom');
      return undefined;
    });
    await restoreFrom(f);
    const alert = await screen.findByRole('alert');
    expect(alert.textContent).not.toBe('');
    expect(alert).not.toHaveTextContent('The version was restored.');
    expect(alert).not.toHaveTextContent('There is nothing to change');
    expect(alert).not.toHaveTextContent('Restore it from Trash first');
  });

  it('clears an earlier message when the next restore starts', async () => {
    let failing = true;
    const f = fake((m) => {
      if (m === 'POST' && failing) throw new ApiError(409, { status: 409, code: 'NOTHING_TO_CHANGE', message: 'x' } as never);
      return undefined;
    });
    await restoreFrom(f);
    expect(await screen.findByRole('alert')).toHaveTextContent('nothing to change');
    failing = false;
    await userEvent.click(within(await row()).getByRole('button', { name: 'Restore' }));
    await userEvent.click(within(await screen.findByRole('dialog')).getByRole('button', { name: 'Restore this version' }));
    expect(await screen.findByRole('status')).toHaveTextContent('The version was restored.');
    expect(screen.queryByRole('alert')).toBeNull();
  });
});

src/features/duplicates/merge-page.test..source:
import { screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ApiError, type ApiClient } from '@/lib/api/client';
import { groupsApi, konferenca, skupno, signedIn } from '@/test/groupsApi';
import { renderApp } from '@/test/renderApp';
import type { Contact } from '@/features/contacts/contactValues';
import { attributeConflicts, combinedTags, preselect } from './MergePage';

const contact = (id: string, createdAt: string, extra: Partial<Contact> = {}): Contact =>
  ({ id, state: 'ACTIVE', createdAt, revision: 3, versionNumber: 1, lastName: 'Novak', ...extra }) as Contact;

const bare = contact('x', '2026-06-01T10:00:00Z');
delete (bare as Partial<Contact>).lastName;

describe('merge helpers on contacts without tags or attributes', () => {
  it('treat missing lists as empty', () => {
    expect(attributeConflicts([bare, bare])).toEqual([]);
    expect(combinedTags([bare, bare])).toEqual([]);
    expect(attributeConflicts([bare, contact('y', bare.createdAt, { attributes: [{ key: 'k', value: 'v' }] })])).toEqual([]);
    expect(combinedTags([bare, contact('y', bare.createdAt, { tags: ['t'] })])).toEqual(['t']);
  });

  it('keeps the first spelling of a key and every value once', () => {
    const one = contact('1', bare.createdAt, { attributes: [{ key: 'Level', value: 'a' }] });
    const two = contact('2', bare.createdAt, { attributes: [{ key: 'level', value: 'b' }, { key: 'level', value: 'a' }] });
    expect(attributeConflicts([one, two])).toEqual([{ key: 'Level', values: ['a', 'b'] }]);
  });

  it('preselects 0 when no contact has a value', () => {
    expect(Object.values(preselect([bare, bare])).every((n) => n === 0)).toBe(true);
  });
});

const a = contact('a', '2026-06-01T10:00:00Z', {
  company: 'Acme',
  country: 'SI',
  tags: ['x'],
  attributes: [{ key: 'Level', value: 'java' }],
});
const b = contact('b', '2026-06-02T10:00:00Z', {
  company: 'Beta',
  phone: '+386 41 555 123',
  country: 'AT',
  tags: ['X', 'y'],
  attributes: [{ key: 'level', value: 'python' }],
});
const c = contact('c', '2026-06-03T10:00:00Z', { tags: ['z'] });

function mergeApi(merge?: (body: unknown) => Promise<unknown>, byId: Record<string, Contact> = { a, b, c }) {
  const { api: groups } = groupsApi([konferenca, skupno]);
  const calls: { method: string; path: string; body?: unknown }[] = [];
  const api: ApiClient = {
    ...groups,
    request: (async (method: string, path: string, body?: unknown) => {
      if (path.startsWith('/groups/g-1/')) calls.push({ method, path, body });
      const one = /\/contacts\/([^/]+)$/.exec(path);
      if (one) return byId[decodeURIComponent(one[1]!)];
      if (path.endsWith('/merges')) return merge ? merge(body) : { ...a, id: 'a' };
      return groups.request(method, path, body);
    }) as ApiClient['request'],
  };
  return { api, calls };
}

const open = (query: string, merge?: (body: unknown) => Promise<unknown>, group = 'g-1') => {
  const fake = mergeApi(merge);
  renderApp(`/groups/${group}/duplicates/merge${query}`, { auth: signedIn(), api: fake.api });
  return fake;
};
const confirm = () => screen.getByRole('button', { name: /Confirm merge|Merging/ });
const refuse = (code: string, errors?: unknown) => async () => {
  throw new ApiError(400, { status: 400, code, message: 'x', errors } as never);
};

describe('MergePage: what it asks for', () => {
  it('reads every contact of ids once, with encoded ids, and links back to the duplicates', async () => {
    const fake = open('?ids=b,a');
    await screen.findByText('Survivor (the oldest, stays)');
    expect(fake.calls.filter((x) => x.method === 'GET').map((x) => x.path).sort()).toEqual([
      '/groups/g-1/contacts/a',
      '/groups/g-1/contacts/b',
    ]);
    const crumb = screen.getByText(/\/ Merge$/);
    expect(within(crumb).getByRole('link', { name: 'Duplicates' })).toHaveAttribute('href', '/groups/g-1/duplicates');
  });

  it('asks for nothing and shows an error when fewer than two ids are given', async () => {
    for (const query of ['', '?ids=a', '?ids=a,,']) {
      const fake = open(query);
      expect(await screen.findByText('Something went wrong. Please try again.')).toBeInTheDocument();
      expect(screen.getByRole('heading', { name: 'Merge contacts' })).toBeInTheDocument();
      expect(screen.queryByText('Survivor (the oldest, stays)')).toBeNull();
      expect(fake.calls).toHaveLength(0);
      document.body.innerHTML = '';
    }
  });

  it('asks for nothing from a Viewer', async () => {
    const fake = open('?ids=a,b', undefined, 'g-3');
    expect(await screen.findByRole('heading', { level: 1, name: 'Skupno' })).toBeInTheDocument();
    await new Promise((r) => setTimeout(r, 50));
    expect(fake.calls).toHaveLength(0);
    expect(screen.queryByText(/\/ Merge$/)).toBeNull();
  });

  it('shows an error with a retry when a contact cannot be read', async () => {
    let failing = true;
    const { api: groups } = groupsApi([konferenca]);
    const api: ApiClient = {
      ...groups,
      request: (async (method: string, path: string, body?: unknown) => {
        if (/\/contacts\/[ab]$/.test(path)) {
          if (failing) throw new ApiError(500, { status: 500, code: 'INTERNAL_ERROR', message: 'x' } as never);
          return path.endsWith('/a') ? a : b;
        }
        return groups.request(method, path, body);
      }) as ApiClient['request'],
    };
    renderApp('/groups/g-1/duplicates/merge?ids=a,b', { auth: signedIn(), api });
    expect(await screen.findByText('Something went wrong. Please try again.')).toBeInTheDocument();
    failing = false;
    await userEvent.click(screen.getByRole('button', { name: 'Try again' }));
    expect(await screen.findByText('Survivor (the oldest, stays)')).toBeInTheDocument();
  });
});

describe('MergePage: the choices', () => {
  it('names the oldest contact the survivor and the others as joining, oldest first', async () => {
    open('?ids=c,b,a');
    await screen.findByText('Survivor (the oldest, stays)');
    const group = screen.getByRole('group', { name: 'Fields' });
    expect(Array.from(group.querySelectorAll('strong')).map((n) => n.textContent)).toEqual([
      'Survivor (the oldest, stays)',
      'Contact to join',
      'Contact to join',
    ]);
  });

  it('preselects the first non-empty value per field, shows the country by name and an empty one as a dash', async () => {
    open('?ids=a,b');
    await screen.findByText('Survivor (the oldest, stays)');
    const group = screen.getByRole('group', { name: 'Fields' });
    const rowOf = (label: string) => within(group).getByText(label, { selector: 'span.font-semibold' }).parentElement as HTMLElement;
    const country = within(rowOf('Country')).getAllByRole('radio');
    expect(country.map((r) => (r as HTMLInputElement).checked)).toEqual([true, false]);
    expect(within(rowOf('Country')).getByText('Slovenia')).toBeInTheDocument();
    expect(within(rowOf('Country')).getByText('Austria')).toBeInTheDocument();
    const phone = within(rowOf('Phone')).getAllByRole('radio') as HTMLInputElement[];
    expect(phone.map((r) => r.checked)).toEqual([false, true]);
    expect(within(rowOf('Phone')).getByLabelText('empty')).toHaveTextContent('–');
    expect(within(rowOf('Phone')).getByText('+386 41 555 123')).toBeInTheDocument();
    const company = within(rowOf('Company')).getAllByRole('radio') as HTMLInputElement[];
    expect(company.map((r) => r.checked)).toEqual([true, false]);
  });

  it('keeps a pick per field and sends exactly what is picked', async () => {
    const fake = open('?ids=b,a');
    await screen.findByText('Survivor (the oldest, stays)');
    const group = screen.getByRole('group', { name: 'Fields' });
    const rowOf = (label: string) => within(group).getByText(label, { selector: 'span.font-semibold' }).parentElement as HTMLElement;
    await userEvent.click(within(rowOf('Company')).getAllByRole('radio')[1]!);
    expect((within(rowOf('Company')).getAllByRole('radio') as HTMLInputElement[]).map((r) => r.checked)).toEqual([false, true]);
    expect((within(rowOf('Country')).getAllByRole('radio') as HTMLInputElement[]).map((r) => r.checked)).toEqual([true, false]);
    await userEvent.click(screen.getByRole('radio', { name: 'python' }));
    await userEvent.click(confirm());
    await waitFor(() => expect(fake.calls.some((x) => x.method === 'POST')).toBe(true));
    const post = fake.calls.find((x) => x.method === 'POST')!;
    expect(post.path).toBe('/groups/g-1/merges');
    const body = post.body as { fields: Record<string, string>; contacts: unknown[]; attributeChoices: unknown[] };
    expect(body.fields.company).toBe('Beta');
    expect(body.fields.country).toBe('SI');
    expect(body.fields.phone).toBe('+386 41 555 123');
    expect(body.contacts).toEqual([
      { id: 'a', revision: 3 },
      { id: 'b', revision: 3 },
    ]);
    expect(body.attributeChoices).toEqual([{ key: 'Level', value: 'python' }]);
  });

  it('lists the combined tags once each and the conflicts with their values; none when there are none', async () => {
    open('?ids=a,b');
    await screen.findByText('Survivor (the oldest, stays)');
    expect(screen.getByRole('heading', { name: 'Combined tags' })).toBeInTheDocument();
    expect(screen.getAllByRole('listitem').map((li) => li.textContent)).toEqual(['x', 'y']);
    expect(screen.getByRole('heading', { name: 'Attribute conflicts' })).toBeInTheDocument();
    expect(screen.getByText('Same key, different values. Choose one per key.')).toBeInTheDocument();
    const fieldset = screen.getByText('Level', { selector: 'legend' }).closest('fieldset') as HTMLElement;
    const radios = within(fieldset).getAllByRole('radio') as HTMLInputElement[];
    expect(radios.map((r) => r.name)).toEqual(['attribute-level', 'attribute-level']);
    expect(radios.map((r) => r.checked)).toEqual([false, false]);
    await userEvent.click(radios[0]!);
    expect(radios.map((r) => r.checked)).toEqual([true, false]);
    await userEvent.click(radios[1]!);
    expect(radios.map((r) => r.checked)).toEqual([false, true]);
  });

  it('shows no conflict section and enables Confirm at once when no key conflicts', async () => {
    open('?ids=a,c');
    await screen.findByText('Survivor (the oldest, stays)');
    expect(screen.queryByRole('heading', { name: 'Attribute conflicts' })).toBeNull();
    expect(confirm()).toBeEnabled();
  });

  it('needs one choice per key before Confirm is enabled', async () => {
    const two = {
      a: contact('a', a.createdAt, { attributes: [{ key: 'One', value: '1' }, { key: 'Two', value: '2' }] }),
      b: contact('b', b.createdAt, { attributes: [{ key: 'one', value: 'x' }, { key: 'two', value: 'y' }] }),
    };
    const { api } = mergeApi(undefined, two);
    renderApp('/groups/g-1/duplicates/merge?ids=a,b', { auth: signedIn(), api });
    await screen.findByText('Survivor (the oldest, stays)');
    expect(confirm()).toBeDisabled();
    await userEvent.click(screen.getByRole('radio', { name: '1' }));
    expect(confirm()).toBeDisabled();
    await userEvent.click(screen.getByRole('radio', { name: 'y' }));
    expect(confirm()).toBeEnabled();
  });
});

describe('MergePage: the outcome', () => {
  it('shows "Merging …" while the request runs, then opens the survivor and refreshes the data', async () => {
    let release: (v: unknown) => void = () => undefined;
    const fake = open('?ids=a,c', () => new Promise((resolve) => (release = resolve)));
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    expect(await screen.findByRole('button', { name: 'Merging …' })).toBeDisabled();
    release({ ...a, id: 'a' });
    await screen.findByRole('heading', { level: 1, name: 'Konferenca 2026' });
    expect(fake.calls.some((x) => x.path === '/groups/g-1/contacts/a' && x.method === 'GET')).toBe(true);
  });

  it('names the attribute limit and the tag limit, and uses the usual text for other refusals', async () => {
    const tooMany = (field: string) => refuse('VALIDATION_FAILED', [{ field, code: 'TOO_MANY', message: 'x' }]);
    open('?ids=a,c', tooMany('attributes[3]'));
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    expect(await screen.findByRole('alert')).toHaveTextContent('A contact has at most 50 attributes.');
    document.body.innerHTML = '';
    open('?ids=a,c', tooMany('tags[1]'));
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    expect(await screen.findByRole('alert')).toHaveTextContent('A contact has at most 50 tags.');
    document.body.innerHTML = '';
    open('?ids=a,c', refuse('CONFLICT'));
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    expect(await screen.findByRole('alert')).toHaveTextContent('This contact was changed by someone else.');
    document.body.innerHTML = '';
    open('?ids=a,c', refuse('VALIDATION_FAILED', [{ field: 'phone', code: 'OTHER', message: 'x' }]));
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    expect(await screen.findByRole('alert')).not.toHaveTextContent('at most 50');
  });

  it('shows the generic text for a failure that is no ApiError', async () => {
    open('?ids=a,c', async () => {
      throw new Error('boom');
    });
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(confirm());
    const alert = await screen.findByRole('alert');
    expect(alert.textContent).not.toBe('');
    expect(alert).not.toHaveTextContent('boom');
  });

  it('leaves the screen on Cancel', async () => {
    open('?ids=a,c');
    await screen.findByText('Survivor (the oldest, stays)');
    await userEvent.click(screen.getByRole('button', { name: 'Cancel' }));
    await waitFor(() => expect(screen.queryByRole('heading', { name: 'Merge contacts' })).toBeNull());
  });
});

